import re

_PHONE_RE = re.compile(r'(?<!\d)(0\d{1,2})([-.\s]?)(\d{3,4})([-.\s]?)(\d{4})(?!\d)')


def _mask_match(m):
    return m.group(1) + m.group(2) + '*' * len(m.group(3)) + m.group(4) + m.group(5)


def mask_phone(text):
    return _PHONE_RE.sub(_mask_match, text)

