import re

_PHONE_RE = re.compile(r'(?<![0-9])0[0-9]{1,2}[-\s]?[0-9]{3,4}[-\s]?[0-9]{4}(?![0-9])')


def _mask_match(match):
    s = match.group(0)
    digit_positions = [i for i, c in enumerate(s) if '0' <= c <= '9']
    n = len(digit_positions)
    start = (n - 4) // 2
    out = list(s)
    for i in digit_positions[start:start + 4]:
        out[i] = '*'
    return ''.join(out)


def mask_phone(text):
    if not isinstance(text, str):
        return text
    return _PHONE_RE.sub(_mask_match, text)

